PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:Monsieur_Taxi dbr:A_Yiddish_World_Remembered }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director's birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?bd1 . }
  OPTIONAL { ?director dbo:birthDate ?bd2 . }
  BIND (COALESCE(?bd1, ?bd2) AS ?birthDate)
}
LIMIT 100

